const ccxt = require('ccxt');

const exchange = new ccxt.binance();

// ดึงข้อมูล 4H 200 แท่ง เพื่อให้ Bollinger Bands และ MACD แม่นขึ้น
const ohlcv = await exchange.fetchOHLCV('BNB/USDT', '1d', undefined, 200);

return ohlcv.map(c => ({
  time: c[0],
  open: c[1],
  high: c[2],
  low: c[3],
  close: c[4],
  volume: c[5]
}));

