// ===== Parse Ollama response → structured fields =====
const body = $input.item.json;
const analysis = body.message?.content || body.choices?.[0]?.message?.content || '';

const SYMBOL = 'BNB/USDT';
const TIMEFRAME = '1D';

const firstMatch = (re) => {
  const m = analysis.match(re);
  return m ? m[1].trim().replace(/\*+$/g, '').trim() : null;
};
const pickNumber = (s) => {
  if (!s) return null;
  const m = s.match(/-?\d+(?:[.,]\d+)?/);
  return m ? parseFloat(m[0].replace(/,/g, '')) : null;
};

// --- Trend ---
const trendBlock = firstMatch(/สรุปแนวโน้ม\s*\n+\s*([^\n]+)/);
let trend = null, trend_reason = null;
if (trendBlock) {
  const m = trendBlock.match(/^([A-Z]+)\s*-\s*เหตุผล\s*[:：]\s*(.+)$/);
  if (m) { trend = m[1]; trend_reason = m[2].trim(); }
  else trend = trendBlock.split(/\s+/)[0];
}

// --- Indicators ---
const stripMd = (s) => s ? s.replace(/^\*+\s*/, '').replace(/\*+$/g, '').trim() : null;
const ema_note      = stripMd(firstMatch(/EMA[^\n:：]*[:：]\s*\**\s*([^\n]+)/));
const macd_note     = stripMd(firstMatch(/\*\*MACD[^\n:：]*[:：]\*\*\s*([^\n]+)/) || firstMatch(/MACD[^\n:：]*[:：]\s*\**\s*([^\n]+)/));
const bollinger_note= stripMd(firstMatch(/Bollinger\s*Bands[^\n:：]*[:：]\s*\**\s*([^\n]+)/i));
const volume_note   = stripMd(firstMatch(/Volume[^\n:：]*[:：]\s*\**\s*([^\n]+)/i));
const rsiLine       = firstMatch(/RSI[^\n:：]*[:：]\s*\**\s*([^\n]+)/);
const rsi           = pickNumber(rsiLine);

// --- Support / Resistance ---
const r1Line = firstMatch(/แนวต้านที่\s*1\s*[:：]\s*([^\n]+)/);
const r2Line = firstMatch(/แนวต้านที่\s*2\s*[:：]\s*([^\n]+)/);
const s1Line = firstMatch(/แนวรับที่\s*1\s*[:：]\s*([^\n]+)/);
const s2Line = firstMatch(/แนวรับที่\s*2\s*[:：]\s*([^\n]+)/);

// --- Recommendation ---
const recLine = firstMatch(/แนวทาง[^\n:：]*[:：]\s*\**\s*([^\n]+)/);
let recommendation = null, recommendation_reason = null;
if (recLine) {
  const m = recLine.match(/^([A-Za-zก-๙]+)\s*-\s*เหตุผล\s*[:：]\s*(.+)$/);
  if (m) { recommendation = m[1]; recommendation_reason = m[2].trim(); }
  else recommendation = recLine.split(/\s+/)[0];
}

const entryLine = firstMatch(/จุด\s*Entry[^\n:：]*[:：]\s*([^\n]+)/i);
const slLine    = firstMatch(/Stop\s*Loss[^\n:：]*[:：]\s*([^\n]+)/i);
const t1Line    = firstMatch(/Target\s*ที่\s*1\s*[:：]\s*([^\n]+)/i);
const t2Line    = firstMatch(/Target\s*ที่\s*2\s*[:：]\s*([^\n]+)/i);

// --- ATR ---
const atrMatch = analysis.match(/ATR\s*([0-9.,]+)/i);
const atr = atrMatch ? parseFloat(atrMatch[1].replace(/,/g, '')) : null;

// --- Risk ---
const riskSection = analysis.match(/⚠️[^\n]*\n([\s\S]+)$/);
const risk_note = riskSection ? riskSection[1].trim() : null;

// --- Timestamps ---
const now = new Date();
const tsThai = now.toLocaleString('th-TH', { timeZone: 'Asia/Bangkok' });

return [
  {
    json: {
      // For Discord (keep backward-compat fields)
      timestamp: tsThai,
      symbol: SYMBOL,
      analysis: analysis,

      // For Postgres insert
      analyzed_at: now.toISOString(),
      coin: SYMBOL,
      timeframe: TIMEFRAME,

      trend,
      trend_reason,

      recommendation,
      recommendation_reason,

      entry_price: pickNumber(entryLine),
      stop_loss: pickNumber(slLine),
      stop_loss_note: slLine,
      target_1: pickNumber(t1Line),
      target_2: pickNumber(t2Line),

      resistance_1: pickNumber(r1Line),
      resistance_1_note: r1Line,
      resistance_2: pickNumber(r2Line),
      resistance_2_note: r2Line,
      support_1: pickNumber(s1Line),
      support_1_note: s1Line,
      support_2: pickNumber(s2Line),
      support_2_note: s2Line,

      rsi,
      atr,

      ema_note,
      macd_note,
      bollinger_note,
      volume_note,
      risk_note,

      raw_text: analysis,
      raw: body
    }
  }
];

